sys_script_include.script:
var FetchPosonDmd = Class.create();
FetchPosonDmd.prototype = {
    initialize: function() {},
    getDmd: function(user) {
        var onDemand = new GlideRecord('x_hsb11_mss_pos_mss_custody_position_ondemand_staging');
        onDemand.addQuery('triggered_by', user);
        onDemand.addQuery('type', 'query');
		onDemand.addQuery('request_body_for_detail','');
		onDemand.addQuery('parent_position_ondemand','');
        onDemand.orderByDesc('sys_created_on');
        onDemand.query();
        if (onDemand.next()) {
            return onDemand.sys_id;
        }
		else
		{
			//In case of Offset
		var arr=[];
		var onDemandOffset = new GlideRecord('x_hsb11_mss_pos_mss_custody_position_ondemand_staging');
        onDemandOffset.addQuery('triggered_by', user);
        onDemandOffset.addQuery('type', 'query');
		onDemandOffset.addQuery('request_body_for_detail','');
		onDemandOffset.addQuery('parent_position_ondemand',onDemand.getValue());
        onDemandOffset.query();
		while(onDemandOffset.next())
		{
			arr.push(onDemand.getValue.toString()+'');
			arr.push(onDemandOffset.sys_id.toString() +'');              

		}
        return (arr.toString());
		}
    },
    type: 'FetchPosonDmd'
};
